  var WH_OPS = [
    opKind('reorder', 'Точка заказа', 'Сколько и что заказать: точка заказа, страховой запас, дни запаса',
      { stock:'Остаток', usage:'Расход в день', lead:'Срок поставки, дн.', safety:3, cover:14 },
      [['stock', 'Остаток (поле)', 'f'], ['usage', 'Средний расход в день (поле)', 'f'], ['lead', 'Срок поставки, дней (поле)', 'f'], ['safety', 'Страховой запас, дней', 'n'], ['cover', 'Заказывать на, дней', 'n']],
      function(rows, p, ctx){
        var k = 0, out = rows.map(function(r){
          var o = cpRow(r), st = nv(r, p.stock), u = nv(r, p.usage), ld = nv(r, p.lead) || 7, sf = +p.safety || 0, cv = +p.cover || 14;
          var rop = u * (ld + sf), status = st <= u * ld ? 'Срочно' : (st <= rop ? 'Заказать' : 'Норма');
          o['Точка заказа'] = r2(rop, 0); o['Запас, дн.'] = u ? r2(st / u, 1) : '∞';
          o['К заказу'] = status === 'Норма' ? 0 : Math.ceil(Math.max(0, u * (ld + sf + cv) - st)); o['Статус'] = status;
          if(status !== 'Норма') k++; return o;
        });
        ctx.info = 'Заказать: ' + k + ' из ' + out.length; ctx.table(ctx.name, out); return out;
      }, function(p){ return 'страховой ' + (p.safety || 0) + ' дн., заказ на ' + (p.cover || 14) + ' дн.'; }),
    opKind('pick', 'Резерв под заказы', 'Резервирует остатки под заказы клиентов по дате (две таблицы на входе)',
      { item:'Артикул', qty:'Количество', stock:'Остаток', date:'Дата' },
      [['item', 'Артикул (поле)', 'f'], ['qty', 'Количество в заказе (поле)', 'f'], ['stock', 'Остаток на складе (поле)', 'f'], ['date', 'Дата заказа (поле)', 'f']],
      function(rows, p, ctx){
        var hasStock = function(set){ return set.length && lookup(set[0], p.stock) !== undefined && lookup(set[0], p.qty) === undefined; };
        var stockSet = ctx.ins.filter(hasStock)[0];
        if(!stockSet){ ctx.log('нужна таблица остатков с полем «' + p.stock + '» — соедините её с этим блоком', 'warn'); ctx.info = 'Нет остатков'; return rows; }
        var left = {}; stockSet.forEach(function(r){ left[sv(r, p.item)] = (left[sv(r, p.item)] || 0) + nv(r, p.stock); });
        var orders = [].concat.apply([], ctx.ins.filter(function(s){ return s !== stockSet; }));
        orders = orders.map(function(r, i){ return { r:r, i:i, d:ruDate(sv(r, p.date)) }; }).sort(function(a, b){ return (a.d || 0) - (b.d || 0) || a.i - b.i; });
        var full = 0, out = orders.map(function(x){
          var o = cpRow(x.r), it = sv(x.r, p.item), need = nv(x.r, p.qty), have = left[it] || 0, give = Math.min(need, have);
          left[it] = have - give; o['Зарезервировано'] = give; o['Не хватает'] = need - give;
          o['Статус'] = give >= need ? 'Собран' : (give > 0 ? 'Частично' : 'Нет в наличии'); if(give >= need) full++; return o;
        });
        ctx.info = 'Собрано полностью: ' + full + ' из ' + out.length; ctx.table(ctx.name, out); return out;
      }, function(p){ return 'по «' + (p.item || '?') + '», очередь по «' + (p.date || '?') + '»'; }),
    opKind('trips', 'Рейсы доставки', 'Раскладывает заказы по машинам с учётом грузоподъёмности и районов',
      { zone:'Район', weight:'Вес, кг', cap:1500, cost:4500, id:'Номер' },
      [['zone', 'Район доставки (поле)', 'f'], ['weight', 'Вес (поле)', 'f'], ['cap', 'Грузоподъёмность машины, кг', 'n'], ['cost', 'Стоимость рейса, руб.', 'n'], ['id', 'Номер заказа (поле)', 'f']],
      function(rows, p, ctx){
        var cap = +p.cap || 1500, g = groupBy(rows, p.zone), trips = [], over = 0;
        g.keys.forEach(function(z){
          var bins = [];
          g.map[z].slice().sort(function(a, b){ return nv(b, p.weight) - nv(a, p.weight); }).forEach(function(r){
            var w = nv(r, p.weight); if(w > cap) over++;
            var b = bins.filter(function(x){ return x.w + w <= cap; })[0];
            if(!b){ b = { w:0, list:[] }; bins.push(b); }
            b.w += w; b.list.push(sv(r, p.id) || '—');
          });
          bins.forEach(function(b){ trips.push({ 'Рейс':'Р-' + (trips.length + 1), 'Район':z, 'Заказов':b.list.length, 'Заказы':b.list.join(', '), 'Вес, кг':r2(b.w, 1), 'Загрузка, %':pct(b.w, cap, 0), 'Стоимость, руб.':+p.cost || 0 }); });
        });
        if(over) ctx.log(plural(over, 'заказ тяжелее', 'заказа тяжелее', 'заказов тяжелее') + ' машины — нужен отдельный транспорт', 'warn');
        ctx.info = 'Рейсов: ' + trips.length + ', затраты ' + money(trips.length * (+p.cost || 0)) + ' руб.'; ctx.table(ctx.name, trips); return trips;
      }, function(p){ return 'машина ' + (p.cap || 1500) + ' кг, рейс ' + money(+p.cost || 0) + ' руб.'; })
  ];
