  // пример для любой отраслевой среды
  function makeEnvDemo(id, k){
    var e = ENVS[id], d = e && e.demos && e.demos[k || 0]; if(!d) return;
    newProj(d.name, null, id);
    var ids = d.spec.map(function(pid){
      var p = pluginById(pid), n = { id:newId('n'), name:p.name, lang:p.lang, x:0, y:0, codes:{}, pluginId:p.id, family:null, desc:p.desc, colors:null };
      G.nodes.push(n); return n;
    });
    d.links.forEach(function(l){ G.edges.push({ id:newId('e'), from:ids[l[0]].id, to:ids[l[1]].id, taps:[] }); });
    var c = viewCenter(); layoutSet(ids, c.x - 900, c.y);
    var minY = Math.min.apply(0, ids.map(function(n){ return n.y; })), minX = Math.min.apply(0, ids.map(function(n){ return n.x; }));
    G.notes.push({ id:newId('t'), text:d.note, x:Math.round(minX), y:Math.round(minY - 200), fs:14, tint:'blue' });
    saveGraph(); renderGraph(); setTimeout(fitView, 30);
    toast('Открыт пример среды «' + e.name + '»');
  }
